[InitializeOnLoad]public static class CanalBeachExpansion{const string D="Assets/Scenes/Oasis/SouthBeach/BeachDetails",C="Assets/Scenes/Oasis/SouthBeach/CanalBankDetails";static List<Vector2> outer;static float[] outerDist;static System.Random rng;static float R(float a,float b)=>a+(float)rng.NextDouble()*(b-a);static CanalBeachExpansion(){EditorApplication.update+=Poll;}static void Poll(){if(EditorApplication.isCompiling||!File.Exists("CanalBeachExpansion.request"))return;File.Delete("CanalBeachExpansion.request");try{Run();}catch(Exception e){File.WriteAllText("FinalEnvironmentRoadReview/CanalBeachExpansion.txt",e.ToString());Debug.LogException(e);}}static float[] Length(List<Vector2> l){var d=new float[l.Count];for(int i=1;i<d.Length;i++)d[i]=d[i-1]+Vector2.Distance(l[i],l[i-1]);return d;}static void Along(List<Vector2> l,float[] d,float s,out Vector2 p,out Vector2 n){int i=1;while(i<d.Length-1&&d[i]<s)i++;var e=l[i]-l[i-1];p=Vector2.Lerp(l[i-1],l[i],Mathf.InverseLerp(d[i-1],d[i],s));n=new Vector2(e.y,-e.x).normalized;}static Vector2 OutNormal(Vector3 p){float best=float.MaxValue;var n=Vector2.zero;for(int i=1;i<outer.Count;i++){var e=outer[i]-outer[i-1];float t=Mathf.Clamp01(Vector2.Dot(new Vector2(p.x,p.z)-outer[i-1],e)/e.sqrMagnitude);float d=(new Vector2(p.x,p.z)-outer[i-1]-t*e).sqrMagnitude;if(d<best){best=d;n=new Vector2(e.y,-e.x).normalized;}}return n;}static Quaternion Face(Vector2 n)=>Quaternion.LookRotation(new Vector3(-n.x,0,-n.y),Vector3.up);
static void Run(){if(AssetDatabase.LoadAssetAtPath<GameObject>(C+"/Canal Bank Beach Details.prefab"))throw new Exception("Already built");Directory.CreateDirectory(C);Directory.CreateDirectory("FinalEnvironmentRoadBackup/BeforeCanalBeachProps");rng=new System.Random(141071);var scene=SceneManager.GetSceneByPath("Assets/Editor/DayNightBackups/Gangstar Final Env.unity");File.Copy(scene.path,"FinalEnvironmentRoadBackup/BeforeCanalBeachProps/Scene.unity",true);File.Copy(D+"/South Coast Beach Details.prefab","FinalEnvironmentRoadBackup/BeforeCanalBeachProps/Outer Details.prefab",true);var roads=scene.GetRootGameObjects().Single(g=>g.name=="Track Roads");var filters=roads.GetComponentsInChildren<MeshFilter>().Where(f=>f.name=="Outer_MEsh"||f.name=="Canal1").ToArray();var probes=new List<GameObject>();var cols=new List<MeshCollider>();foreach(var f in filters){var g=new GameObject("Temporary beach expansion probe");g.transform.position=f.transform.position;g.transform.rotation=f.transform.rotation;g.transform.localScale=f.transform.lossyScale;var col=g.AddComponent<MeshCollider>();col.sharedMesh=f.sharedMesh;probes.Add(g);cols.Add(col);}Physics.SyncTransforms();var yard=roads.GetComponentsInChildren<MeshFilter>().Single(f=>f.name=="Yatch_Port");var exclusion=yard.GetComponent<Renderer>().bounds;exclusion.Expand(new Vector3(35,40,35));Func<Vector2,Vector3?> Ground=p=>{var q=new Vector3(p.x,28,p.y);if(exclusion.Contains(q))return null;float best=-999;Vector3 found=Vector3.zero;foreach(var col in cols){RaycastHit hit;if(col.Raycast(new Ray(new Vector3(p.x,100,p.y),Vector3.down),out hit,150)&&hit.point.y>best){best=hit.point.y;found=hit.point;}}if(best<25.5f||best>28.05f)return null;return found;};var palette=new[]{"Blue","Coral","Green"};var bench=new GameObject("Existing city beach bench");var source=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Scenes/Oasis/3D/Prefeb/Bench.prefab");var child=(GameObject)PrefabUtility.InstantiatePrefab(source,bench.transform);child.trans