var lines=new[]{new List<Vector2>{new Vector2(117.3f,575),new Vector2(117.3f,350),new Vector2(114.23f,0),new Vector2(114.23f,-350),new Vector2(122.72f,-401.25f),new Vector2(139.55f,-426.81f),new Vector2(159.39f,-447.31f),new Vector2(180.58f,-463.61f),new Vector2(220.87f,-482.45f),new Vector2(283.08f,-492.45f),new Vector2(410.9f,-493.91f),new Vector2(660,-494)},new List<Vector2>{new Vector2(-15.3f,575),new Vector2(-15.3f,-690)}};var root=new GameObject("Canal Bank Beach Details");var sectors=new Dictionary<string,GameObject>();int trees=0,rocks=0,furniture=0,benches=0,clusters=0;Vector3 cameraTarget=Vector3.zero;Action<string,Vector3,Vector2,int,int,float> Add=(path,pos,n,bank,k,scale)=>{string key=bank+"_"+k;GameObject sector;if(!sectors.TryGetValue(key,out sector)){sector=new GameObject("Canal beach sector "+key);sector.transform.SetParent(root.transform,false);sectors[key]=sector;}var g=(GameObject)PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>(path),sector.transform);g.transform.position=pos;g.transform.localScale*=scale;bool seating=path.Contains("Furniture")||path.Contains("Bench");g.transform.rotation=seating?Face(n):Quaternion.Euler(0,R(0,360),0);if(path.Contains("Boulder"))g.transform.localScale=Vector3.Scale(g.transform.localScale,new Vector3(R(.9f,1.4f),R(.7f,1.15f),R(.9f,1.4f)));};Func<Vector2,bool> Safe=p=>!((p.x<160&&Mathf.Abs(p.y)<38)||(p.x<160&&Mathf.Abs(p.y-510)<42));for(int bank=0;bank<2;bank++){var len=Length(lines[bank]);for(float s=75;s<len.Last()-65;s+=R(34,49)){Along(lines[bank],len,s,out var q,out var n);if(bank==1)n=-n;var ground=Ground(q-n*R(bank==0?17:13,bank==0?20:16));if(ground.HasValue&&Safe(q)){Add(D+"/Existing Curved City Palm.prefab",ground.Value,n,bank,(int)(s/120),R(.68f,.88f));trees++;}}
for(float s=90;s<len.Last()-70;s+=R(44,65)){Along(lines[bank],len,s,out var q,out var n);if(bank==1)n=-n;var ground=Ground(q-n*(bank==0?15.5f:13.8f));if(ground.HasValue&&Safe(q)){Add(D+"/"+palette[furniture%3]+" Colorful Beach Furniture.prefab",ground.Value,n,bank,(int)(s/120),.90f);cameraTarget=ground.Value;furniture++;if(furniture%2==0){var b=Ground(q-n*(bank==0?18:16)+new Vector2(n.y,-n.x)*5);if(b.HasValue){Add(C+"/Existing City Beach Bench.prefab",b.Value,n,bank,(int)(s/120),1);benches++;}}}}
for(float s=110;s<len.Last()-70;s+=R(65,98)){Along(lines[bank],len,s,out var q,out var n);if(bank==1)n=-n;if(!Safe(q))continue;var tangent=new Vector2(n.y,-n.x);int count=clusters%2==0?3:2;int made=0;for(int j=0;j<count;j++){var ground=Ground(q-n*R(11.5f,14)+tangent*(j*2.0f+R(-.5f,.5f)));if(ground.HasValue){Add(D+"/Beach Granite Boulder "+(rocks%4)+".prefab",ground.Value-Vector3.up*R(.2f,.4f),n,bank,(int)(s/120),R(.35f,.7f));rocks++;made++;}}if(made>0)clusters++;}}
