foreach(float s in new[]{45f,80f,115f,outerDist.Last()-45,outerDist.Last()-80,outerDist.Last()-115}){Along(outer,outerDist,s,out var q,out var n);var pos=Ground(q-n*18);if(!pos.HasValue)continue;var sector=outside.transform.Cast<Transform>().First();var g=(GameObject)PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>(D+"/Existing Curved City Palm.prefab"),sector);g.transform.position=pos.Value;g.transform.rotation=Quaternion.Euler(0,R(0,360),0);g.transform.localScale=Vector3.one*R(.75f,1);outerPalms++;}
